## Default Methods: Write Once, Use Everywhere

```xiom
pub interface Greet {
  fn name(self: &Self) -> Str;  // Required: each type implements

  fn greeting(self: &Self) -> Str {  // Default: shared implementation
    return "Hello, " + self.name() + "!";
  }

  fn farewell(self: &Self) -> Str {  // Default: shared implementation
    return "Goodbye, " + self.name() + "!";
  }
}
```

### Overriding Defaults
```xiom
pub type Admin = { username: Str; }

impl Greet for Admin {
  fn name(self: &Admin) -> Str { return self.username; }

  // Override the default greeting for admins
  fn greeting(self: &Admin) -> Str {
    return "Welcome, Admin " + self.name() + "!";
  }
  // farewell uses the default
}
```

### Default Methods from Other Methods
```xiom
pub interface Comparable[T] {
  fn compare(self: &T, other: &T) -> Ordering;  // Required

  fn less_than(self: &T, other: &T) -> Bool {    // Default
    return self.compare(other) == Ordering::Less;
  }

  fn greater_than(self: &T, other: &T) -> Bool {  // Default
    return self.compare(other) == Ordering::Greater;
  }

  fn equals(self: &T, other: &T) -> Bool {  // Default
    return self.compare(other) == Ordering::Equal;
  }
}
```

Now implementors only need to provide `compare` — they get less_than, greater_than, and equals for free!

