pub interface Describable {
  fn summary(self: &Self) -> Str;

  fn detail(self: &Self) -> Str {
    return self.summary() + " (detailed)";
  }
}

pub type Task = {
  title: Str;
  done: Bool;
}

impl Describable for Task {
  fn summary(self: &Task) -> Str {
    let status = if self.done { "done" } else { "pending" };
    return self.title + " [" + status + "]";
  }
}

fn main() -> Int {
  let t = Task{ title: "Write tests", done: false };
  let d = t.detail();  // Uses default
  return t.title.len();
}
